-- =====================================================================
-- Operations Assistant - Factory Database DDL & Seed Dataset
-- Target Database: MySQL 8.0+ / SQLite 3
-- Generated on: 2026-09-28
-- Description: Consolidated DDL and complete 460 factory records
--              (120 machines, 180 downtimes, 160 maintenance requests)
-- =====================================================================

CREATE DATABASE IF NOT EXISTS factory_ops_db
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE factory_ops_db;

-- ---------------------------------------------------------------------
-- 1. Table: machines
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS maintenance_requests;
DROP TABLE IF EXISTS downtime;
DROP TABLE IF EXISTS machines;

CREATE TABLE machines (
    machine_id VARCHAR(50) NOT NULL COMMENT 'Unique identifier for the machine asset',
    machine_name VARCHAR(120) NOT NULL COMMENT 'Descriptive machine model name',
    location VARCHAR(120) NOT NULL COMMENT 'Plant location or bay identifier',
    status VARCHAR(30) NOT NULL DEFAULT 'OPERATIONAL' COMMENT 'Current operational state',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Audit creation timestamp',
    PRIMARY KEY (machine_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 2. Table: downtime
-- ---------------------------------------------------------------------
CREATE TABLE downtime (
    downtime_id INT AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key',
    machine_id VARCHAR(50) NOT NULL COMMENT 'Foreign key to machines',
    date DATE NOT NULL COMMENT 'Stoppage date',
    duration_hours DECIMAL(5, 2) NOT NULL COMMENT 'Outage duration in hours',
    reason VARCHAR(255) NOT NULL COMMENT 'Failure root cause',
    PRIMARY KEY (downtime_id),
    INDEX idx_downtime_machine_date (machine_id, date),
    INDEX idx_downtime_date (date),
    CONSTRAINT fk_downtime_machine FOREIGN KEY (machine_id) REFERENCES machines(machine_id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 3. Table: maintenance_requests
-- ---------------------------------------------------------------------
CREATE TABLE maintenance_requests (
    request_id INT AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key',
    machine_id VARCHAR(50) NOT NULL COMMENT 'Foreign key to machines',
    description TEXT NOT NULL COMMENT 'Maintenance task description',
    priority VARCHAR(20) NOT NULL DEFAULT 'MEDIUM' COMMENT 'Urgency: LOW, MEDIUM, HIGH, CRITICAL',
    status VARCHAR(30) NOT NULL DEFAULT 'PENDING' COMMENT 'Workflow state: PENDING, APPROVED, IN_PROGRESS, COMPLETED',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Creation timestamp',
    PRIMARY KEY (request_id),
    INDEX idx_maintenance_machine (machine_id),
    INDEX idx_maintenance_status (status),
    INDEX idx_maintenance_created_at (created_at),
    CONSTRAINT fk_maintenance_machine FOREIGN KEY (machine_id) REFERENCES machines(machine_id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

